export const recruiterGuide: RoleGuide = {
  role: 'standard',
  label: 'Recruiter',
  tagline: 'Read-only access to job descriptions, résumés and the candidate pipeline.',
  intro: [
    'This is the guide for the **Recruiter** role. It covers every screen you can open and every control on them, in the order you meet them: signing in, the dashboard, the Recruiting workspace, the activity log, and a glossary at the end.',
    'A Recruiter account is read-only. You can follow the whole hiring loop, but an HR Admin or Super Admin carries it out: they write or import a job description, upload résumés against it, set up each interview (the AI interview on this platform, or a meeting run on Zoom, Google Meet or Teams), record the interviewers\' scorecards or read the AI report, and make the offer. You browse job descriptions and résumés, read the candidate pipeline, and open each candidate\'s résumé, Fit Snapshot and Timeline.',
    'Scoring never emails a candidate on its own, unless your deployment has switched on automatic invitations, which is off by default. A high match score does not email anyone: HR chooses, candidate by candidate, between an AI interview on this platform and an interview on another platform. If the interview is on another platform, a scorecard must be submitted afterwards before Hire or Send offer become available.',
    'What a Recruiter account receives is limited. You never receive an interview report, score, transcript, integrity data or scorecard, anywhere in the product: those go to admins only. You do see each candidate\'s match percentage. If your account has a department set, you only see that department\'s jobs and candidates, and a job with no department stays visible to everyone. The server also accepts changes to jobs, résumés and candidates (creating or importing a job description, uploading résumés, setting up an interview, shortlisting, rejecting, hiring, offers) from an HR Admin or Super Admin account only, so a Recruiter account is not shown those controls.',
    'A handful of controls on these screens belong to HR Admins or Super Admins. They are still documented, each one is marked with the role it needs, so that when a button is missing from your screen you can see exactly why and who to ask.',
    'Two things are worth internalising before you start. The candidate pipeline hides anyone below a **50% match score** by default, which is the single most common reason a candidate "is missing". And the **Activity** page explains what happened to every upload, which is the single most common reason an upload "did nothing".',
  ],
  chapters: coreChapters,
}

export default recruiterGuide
